package br.com.mecaniQA.api.Repository;
import br.com.mecaniQA.api.model.*; import br.com.mecaniQA.api.Mappers.ClienteResultSetMapper; import br.com.mecaniQA.api.Enums.*; import java.sql.*; import java.util.*; import java.time.*;
public class ClienteRepository extends JdbcSupport implements Repository<Cliente,Long> {
 private static final ClienteRepository INSTANCE=new ClienteRepository(); public static ClienteRepository getInstance(){return INSTANCE;}
 public Cliente cadastrar(Cliente x){return save(x);} public List<Cliente> listarTodos(){return findAll();} public Cliente buscarPorId(Long id){return findById(id).orElse(null);} public Cliente buscarPorCpfCnpj(String cpf){return query("SELECT * FROM clientes WHERE cpf_cnpj=?",new ClienteResultSetMapper()::map,cpf).stream().findFirst().orElse(null);} public Cliente atualizar(Long id,Cliente x){x.setIdCliente(id);return update(x);} public Cliente deletar(Long id){Cliente x=buscarPorId(id);if(x!=null)deleteById(id);return x;} public int getTotalClientes(){return findAll().size();} public void limpar(){execute("DELETE FROM clientes");}
 public Cliente save(Cliente x){long id=insert("INSERT INTO clientes(nome,cpf_cnpj,email,telefone,endereco,cidade,estado,cep) VALUES(?,?,?,?,?,?,?,?)",x.getNome(),x.getCpfCnpj(),x.getEmail(),x.getTelefone(),x.getEndereco(),x.getCidade(),x.getEstado(),x.getCep());x.setIdCliente(id);return x;}
 public Optional<Cliente> findById(Long id){return query("SELECT * FROM clientes WHERE id_cliente=?",new ClienteResultSetMapper()::map,id).stream().findFirst();} public List<Cliente> findAll(){return query("SELECT * FROM clientes ORDER BY id_cliente",new ClienteResultSetMapper()::map);} public Cliente update(Cliente x){int n=execute("UPDATE clientes SET nome=?,cpf_cnpj=?,email=?,telefone=?,endereco=?,cidade=?,estado=?,cep=?,data_atualizacao=CURRENT_TIMESTAMP WHERE id_cliente=?",x.getNome(),x.getCpfCnpj(),x.getEmail(),x.getTelefone(),x.getEndereco(),x.getCidade(),x.getEstado(),x.getCep(),x.getIdCliente());return n==0?null:x;} public void deleteById(Long id){execute("DELETE FROM clientes WHERE id_cliente=?",id);} public boolean existsById(Long id){return !query("SELECT id_cliente FROM clientes WHERE id_cliente=?",r->r.getLong(1),id).isEmpty();}
 private Cliente map(ResultSet r)throws SQLException{Cliente x=new Cliente();setId(x,"idCliente",r.getLong("id_cliente"));x.setNome(r.getString("nome"));x.setCpfCnpj(r.getString("cpf_cnpj"));x.setEmail(r.getString("email"));x.setTelefone(r.getString("telefone"));x.setEndereco(r.getString("endereco"));x.setCidade(r.getString("cidade"));x.setEstado(r.getString("estado"));x.setCep(r.getString("cep"));x.setDataAtualizacao(time(r,"data_atualizacao"));return x;}
}
